#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6

HOST="${SUKKAL_HOST:-amaterasu}"
REMOTE_USER="${SUKKAL_REMOTE_USER:-shanedolley}"
CANDIDATE=/tmp/sukkal-sudoers
TARGET=/etc/sudoers.d/sukkal

# The file itself. Read it before running anything: it is the whole change.
read -r -d '' SUDOERS <<'FILEEOF' || true
# Passwordless sudo on amaterasu.
#
# This grants every command as any user, with no password prompt.
#
# It grants no new commands. shanedolley already holds (ALL : ALL) ALL through
# the sudo group, so the only thing removed here is the password step.
#
# The consequence, recorded on purpose: any process running as shanedolley can
# become root without being asked. That includes a script, an agent, and
# anything that reaches a shell as this user. This box also serves NFS and runs
# NZBGet, so that reach is not limited to one project.
#
# Installed by scripts/setup-sudoers-amaterasu.sh in the sukkal repository.
# Remove with: sudo rm /etc/sudoers.d/sukkal

@@USER@@ ALL=(ALL:ALL) NOPASSWD: ALL
FILEEOF
SUDOERS="${SUDOERS//@@USER@@/$REMOTE_USER}"

banner "Passwordless sudo for $REMOTE_USER on $HOST"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight"

if ssh -o ConnectTimeout=8 -o BatchMode=yes "$HOST" true 2>/dev/null; then
  say "  ${GREEN}ok${RESET}  ssh to $HOST works with a key"
else
  say "  ${RED}no${RESET}  ssh to $HOST failed. Fix that first."; exit 1
fi

if ssh -o BatchMode=yes "$HOST" "test -f $TARGET" 2>/dev/null; then
  warn "$TARGET already exists on $HOST. This run will overwrite it."
fi

# Baseline the drop-ins that are already there. visudo -c fails on any file
# whose mode is not 0440, and it reports every file in one run, so a fault that
# predates this change reads as one this change caused. Stage 5 learned that
# the hard way: it told a user to remove a file that had just parsed cleanly.
# /etc/sudoers.d is world-readable, so this needs no password.
# `|| true` matters: the library sets `set -e`, and a bare assignment takes the
# exit status of its command substitution. The remote loop returns non-zero
# whenever the last file it checks is not mode 440, which would kill the wizard
# here for no reason.
PREEXISTING=$(ssh -o BatchMode=yes "$HOST" \
  'for f in /etc/sudoers.d/*; do m=$(stat -c %a "$f"); [ "$m" = "440" ] || printf "%s (mode %s)\n" "$f" "$m"; done' 2>/dev/null || true)
if [[ -n "$PREEXISTING" ]]; then
  echo
  warn "these files already fail visudo -c, before this run changes anything:"
  printf '%s\n' "$PREEXISTING" | sed 's/^/      /'
  note "sudo still honours them at run time. visudo -c is stricter than sudo is."
  note "Stage 5 knows about these and will not blame them on the new file."
fi

echo
say "${BOLD}What you have now:${RESET}"
ssh -o BatchMode=yes "$HOST" 'sudo -n -l 2>/dev/null | sed -n "/may run/,\$p"' | sed 's/^/    /'
echo
say "${BOLD}What this adds:${RESET}"
printf '%s\n' "$SUDOERS" | grep -v '^#' | grep -v '^$' | sed 's/^/    /'
echo
warn "After this, anything running as $REMOTE_USER can take root without a prompt."
say "  You already hold full sudo. This removes the password, not a restriction."
say "  Undo at any time with: ${BOLD}ssh $HOST sudo rm $TARGET${RESET}"
echo
confirm "Continue?" || { say "Nothing changed."; exit 0; }

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Build the file and prove it parses"
say "A malformed sudoers file breaks every sudo, including the one that fixes it."
say "So the file is validated before your password is ever asked for."
echo

printf '%s\n' "$SUDOERS" | ssh -o BatchMode=yes "$HOST" "cat > $CANDIDATE && chmod 600 $CANDIDATE"
say "  wrote the candidate to $CANDIDATE on $HOST"

if ssh -o BatchMode=yes "$HOST" "visudo -c -f $CANDIDATE" 2>&1 | sed 's/^/    /'; then
  say "  ${GREEN}ok${RESET}  the file parses"
else
  say "  ${RED}no${RESET}  the file does not parse. Nothing was installed."
  ssh -o BatchMode=yes "$HOST" "rm -f $CANDIDATE"
  exit 1
fi
echo
say "${BOLD}The exact file that will be installed:${RESET}"
printf '%s\n' "$SUDOERS" | sed 's/^/    /'
echo
pause "Read it, then continue"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Open a safety net"
say "The file parses on its own. It could still conflict with the wider tree."
say "One live sudo session on $HOST makes any mistake recoverable in seconds."
echo
step "Open a second terminal."
step "Run: ${BOLD}ssh $HOST${RESET}"
step "Run: ${BOLD}sudo -v${RESET}   and type your password there."
step "Leave that terminal open until this wizard finishes."
echo
note "If sudo ever breaks, that session still works. Recover with:"
note "  sudo rm $TARGET"
echo
confirm "Is the second terminal open with an active sudo session?" \
  || { say "Stopping. Nothing was installed."; ssh -o BatchMode=yes "$HOST" "rm -f $CANDIDATE"; exit 0; }

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Install"
say "${BOLD}Type your sudo password when $HOST asks. It goes to sudo, nowhere else.${RESET}"
say "This is the last time it will ask."
echo
ssh -t "$HOST" "sudo install -o root -g root -m 0440 $CANDIDATE $TARGET && rm -f $CANDIDATE"
say "  ${GREEN}ok${RESET}  installed at $TARGET, owned by root, mode 0440"
pause "Continue to verification?"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Verify"
say "Three checks. The first one is the one that matters."
echo

FAILED=0

# Check the whole tree, because a drop-in can parse alone and still conflict
# with what is there. But read the result per file, not by exit code.
#
# visudo -c returns non-zero when ANY file fails, including one that was
# already failing before this run. An earlier version of this stage read the
# exit code alone, called the tree broken, and told a user to remove a file
# whose own line said "parsed OK". Only the line for $TARGET decides whether
# this change is at fault.
# `|| true` is load bearing. The library sets `set -e`, and a bare assignment
# takes the exit status of its command substitution. visudo -c returns non-zero
# whenever any file in the tree fails, which is the normal case this stage
# exists to interpret. Without the guard the wizard dies on this line, printing
# the stage header and nothing else.
TREE=$(ssh -o BatchMode=yes "$HOST" 'sudo -n visudo -c' 2>&1 || true)
if [[ -z "$TREE" ]]; then
  say "  ${RED}no${RESET}  visudo produced no output. The check cannot be trusted."
  exit 1
fi
printf '%s\n' "$TREE" | sed 's/^/    /'

if printf '%s\n' "$TREE" | grep -q "^$TARGET: parsed OK"; then
  say "  ${GREEN}ok${RESET}  $TARGET parses"
elif printf '%s\n' "$TREE" | grep -q "^$TARGET"; then
  say "  ${RED}no${RESET}  $TARGET is the file at fault"
  echo
  say "${RED}${BOLD}Use the second terminal now:${RESET}"
  say "  ${BOLD}sudo rm $TARGET${RESET}"
  exit 1
else
  say "  ${RED}no${RESET}  visudo did not report on $TARGET at all"
  say "      Check that the file installed and that its name has no dot."
  exit 1
fi

# Anything else that failed. Name it, and say plainly that it is not this run's
# doing, so nobody removes a working file to chase someone else's problem.
OTHERS=$(printf '%s\n' "$TREE" | grep -v ': parsed OK$' | grep -v '^$' || true)
if [[ -n "$OTHERS" ]]; then
  echo
  warn "other files in the tree have problems that predate this run:"
  printf '%s\n' "$OTHERS" | sed 's/^/      /'
  note "sudo still honours those files. Fix them separately, or leave them."
  SKIPPED+=("pre-existing visudo -c complaints, listed above, unrelated to this change")
fi

if ssh -o BatchMode=yes "$HOST" 'sudo -n true' 2>/dev/null; then
  say "  ${GREEN}ok${RESET}  sudo runs without a password"
else
  say "  ${RED}no${RESET}  sudo still asks for a password"; FAILED=1
fi

if ssh -o BatchMode=yes "$HOST" 'sudo -n -l' 2>/dev/null | grep -q 'NOPASSWD: ALL'; then
  say "  ${GREEN}ok${RESET}  the grant is in effect"
else
  say "  ${RED}no${RESET}  the grant is not showing up in sudo -l"; FAILED=1
fi
echo
[[ $FAILED -eq 0 ]] || { say "${YELLOW}Installed, but not working as intended. Consider removing it.${RESET}"; exit 1; }
say "${GREEN}Passwordless sudo is active on $HOST.${RESET}"
pause "One last screen"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Keep this"
say "${BOLD}To undo:${RESET}"
say "    ssh $HOST sudo rm $TARGET"
echo
say "${BOLD}To check it is still there:${RESET}"
say "    ssh $HOST sudo -n -l"
echo
say "${BOLD}What changed:${RESET}"
say "    $TARGET now grants $REMOTE_USER every command with no password."
say "    Nothing else on the box was touched. The existing claude-code and"
say "    nzbget drop-ins are still there and are now redundant."
echo
say "${BOLD}Next:${RESET}"
say "    ./scripts/provision-amaterasu.sh now runs with no prompt at all."
echo
SKIPPED+=("close the second terminal: its sudo session is no longer the safety net")
finish
